arguments.command:
env | grep -iE '^(http|https|all|no)_proxy=' || echo 'NO_PROXY_ENV'; echo '--- socket test ---'; python3 - <<'EOF'
import socket
try:
    s = socket.create_connection(("127.0.0.1", 1), timeout=2)
    print("loopback connect OK")
    s.close()
except Exception as e:
    print("loopback connect failed:", repr(e))
try:
    print("resolve localhost:", socket.gethostbyname("localhost"))
except Exception as e:
    print("resolve localhost failed:", repr(e))
EOF
